#!/bin/sh
# Entrypoint for the MiniCRM / dev-oidc development image.
#
# The local Dovecot container serves IMAP with a self-signed certificate whose CA is
# generated by the compose "certgen" service and mounted at /certs. Go verifies IMAP TLS
# certificates against the system roots, so build a combined bundle and point Go at it via
# SSL_CERT_FILE. This keeps the system trust store untouched and works as a non-root user.
set -eu

# The certificates are generated by the compose "certgen" service. Wait for them when
# the /certs volume is present (the dev-oidc container does not mount it).
if [ -d /certs ]; then
    tries=0
    while [ ! -s /certs/ca.crt ] && [ "$tries" -lt 60 ]; do
        tries=$((tries + 1))
        sleep 1
    done
fi

if [ -f /certs/ca.crt ]; then
    cat /etc/ssl/certs/ca-certificates.crt /certs/ca.crt > /tmp/minicrm-ca-bundle.crt
    export SSL_CERT_FILE=/tmp/minicrm-ca-bundle.crt
fi

# The attachments volume is created by the container runtime and may be root-owned.
if [ "$(id -u)" = "0" ]; then
    mkdir -p "${MINICRM_ATTACHMENTS_DIR:-/data/attachments}"
    chown -R minicrm:minicrm "${MINICRM_ATTACHMENTS_DIR:-/data/attachments}"
    exec su-exec minicrm "$@"
fi

exec "$@"
